});

const clean = value => String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'").replace(/\s+/g, ' ').trim();
const cleanTitle = value => clean(value).replace(/\s+[–—-]\s+[^–—-]{2,70}$/, '').trim();
const now = new Date();
const seen = new Set();
const candidates = [];

for (const item of $input.all()) {
  const row = item.json || {};
  const title = cleanTitle(row.title || row.name || '');
  const url = clean(row.link || row.guid || row.url || '');
  const raw = clean((row.title || '') + ' ' + (row.contentSnippet || row.content || row.description || row.summary || ''));
  if (!title || !raw) continue;

  const publishedRaw = row.isoDate || row.pubDate || row.date || row.published || '';
  const published = publishedRaw && !Number.isNaN(new Date(publishedRaw).getTime()) ? new Date(publishedRaw) : null;
  if (published && (now - published) / 86400000 > 400) continue;

  const key = (url || title).toLowerCase().replace(/[?#].*$/, '').replace(/\/$/, '');
  if (!key || seen.has(key)) continue;
  seen.add(key);
  candidates.push({
    subject: title,
