  });
}

return [{ json: { candidates } }];

const candidates = $('Normalizuj RSS').first().json.candidates || [];
const existingRows = $input.all().map(item => item.json || {});
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const normalize = value => clean(value).toLowerCase().replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
const canonicalUrl = value => clean(value).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/$/, '');
const signature = value => normalize(value)
  .replace(/\b(nabor|zgloszenia|zespolow|zespoly|open call|band applications?|festiwal|festival|przeglad|konkurs|eliminacje|edycja|202[0-9])\b/g, ' ')
