const feeTerms = ['oplata zgloszeniowa','application fee','entry fee','registration fee'];
const closedTerms = ['nabor zamkniety','zgloszenia zamkniete','applications closed','deadline passed','odwolany','cancelled','canceled','nie odbedzie sie'];
const existingNames = new Set();
const existingSignatures = new Set();
const existingUrls = new Set();
