    reasons.push('wygląda na bezpłatne');
  }
  const hasCurrentYear = new RegExp('\\b(' + thisYear + '|' + nextYear + ')\\b').test(probe);
  if (hasCurrentYear) {
    score += 8;
    reasons.push('aktualna edycja');
  }
  if (hasAny(probe, ['deadline','termin zgloszen','do kiedy','applications until','zgloszenia do'])) {
    score += 6;
    reasons.push('podany termin');
  }

  if (hasAny(probe, payTerms)) {
    score -= 50;
    redFlags.push('możliwe pay-to-play / obowiązek sprzedaży biletów');
  }
  if (hasAny(probe, feeTerms)) {
    score -= 25;
    redFlags.push('możliwa opłata zgłoszeniowa');
  }
  if (hasAny(probe, closedTerms)) {
    score -= 45;
    redFlags.push('nabór może być zamknięty albo wydarzenie odwołane');
  }
  if (new RegExp('\\b' + previousYear + '\\b').test(probe) && !hasCurrentYear) {
    score -= 35;
    redFlags.push('wynik może dotyczyć poprzedniej edycji');
  }
  score = Math.max(0, Math.min(100, score));
  if (score < 60) continue;

  const url = clean(candidate.url);
  const urlKey = canonicalUrl(url);
  const nameKey = normalize(title);
  const sigKey = signature(title);
