    : 'Cześć,\n\ntrafiliśmy na nabór do ' + title + ' i wygląda to jak kierunek bliski Viryi. Gramy nowoczesny metal na styku progresji, metalcore’u i elektroniki; jesteśmy z Wrocławia.\n\nDacie znać, czy zgłoszenia są nadal otwarte i bezpłatne oraz gdzie znajdziemy właściwy formularz lub wymagania?\n\nEPK: https://virya.music/pl/epk/\n\nDzięki,\nVirya';
  const runIso = now.toISOString();

  output.push({ json: {
    'Zgłoszenie_ID': submissionId,
    'Event_ID': 'EVT-SC-' + shortHash,
    'Wydarzenie': title,
    'Status_bookingu': 'Nie wysłano',
    'Priorytet': priority,
    'Właściciel': '',
    'Data_wysłania': '',
    'Data_follow_up': '',
    'Odpowiedź': '',
    'Następny_krok': 'Zweryfikować oficjalną stronę, deadline, formularz i bezpłatność zgłoszenia',
    'Uwagi': clean(candidate.raw).slice(0, 480),
    'Akcja_n8n': 'Research_only',
    'N8N_status': 'Nowe znalezisko',
    'N8N_last_run': runIso,
    'Email_do': '',
    'Email_temat': subject.slice(0, 220),
