const NL = String.fromCharCode(10);
const out = [];
const seen = new Set();

const genericLabels = new Set([
  'google', 'facebook', 'twitter', 'x', 'oznacz jako nieistotne',
  'zobacz więcej wyników', 'edytuj ten alert', 'wyświetl wszystkie swoje alerty',
