]);

function decodeEntities(value) {
  return String(value ?? '')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&#x27;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function cleanText(value) {
  return decodeEntities(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalTarget(raw) {
  let value = decodeEntities(raw).trim();
  while (value && '.,;)]}>'.includes(value.slice(-1))) value = value.slice(0, -1);
  try {
    const u = new URL(value);
    const host = u.hostname.toLowerCase().replace(/^www\./, '');

    const isGoogle =
      host === 'google.com' ||
      host === 'google.pl' ||
      host.endsWith('.google.com') ||
      host.endsWith('.google.pl');

    if (isGoogle) {
      for (const key of ['url', 'ru']) {
        const nested = u.searchParams.get(key);
        if (nested) return canonicalTarget(nested);
      }
      return '';
    }

    if (
      host.endsWith('googleusercontent.com') ||
      host.endsWith('gstatic.com') ||
      host === 'schema.org'
    ) return '';

    u.hash = '';
    for (const key of [...u.searchParams.keys()]) {
      const lower = key.toLowerCase();
      if (
        lower.startsWith('utm_') ||
        ['fbclid', 'gclid', 'mc_cid', 'mc_eid'].includes(lower)
      ) u.searchParams.delete(key);
    }
    u.hostname = u.hostname.toLowerCase();

    let result = u.toString();
    if (result.endsWith('/')) result = result.slice(0, -1);
    return result;
  } catch {
    return '';
  }
}

function addCandidate(message, rawUrl, label, context) {
  const url = canonicalTarget(rawUrl);
  if (!url || seen.has(url)) return;

  const cleanedLabel = cleanText(label);
  const lowerLabel = cleanedLabel.toLowerCase();
  if (!cleanedLabel || genericLabels.has(lowerLabel)) return;

  const subject = cleanText(message.Subject || message.subject || 'Google Alert');
  const snippet = cleanText(context || message.snippet || message.textPlain || message.text || '');
  seen.add(url);
  out.push({
    json: {
      title: cleanedLabel || subject,
      link: url,
      contentSnippet: snippet.slice(0, 5000),
      isoDate: message.Date || message.date || message.internalDate || '',
      creator: 'Google Alerts',
      _source_type: 'GMAIL_ALERT',
    },
  });
}

for (const { json: message } of $input.all()) {
  const plain = [
    message.textPlain,
    message.text,
    message.body,
    message.snippet,
  ].filter(v => typeof v === 'string' && v.trim()).join(NL);

  const html = [
    message.textHtml,
    message.html,
  ].filter(v => typeof v === 'string' && v.trim()).join(NL);

  const structured = [];

  const markdownRe = /\[([^\]]{1,500})\]\((https?:\/\/[^)\s]+)\)/g;
  for (const match of plain.matchAll(markdownRe)) {
    structured.push({
      index: match.index ?? 0,
      end: (match.index ?? 0) + match[0].length,
      label: match[1],
      url: match[2],
      source: plain,
    });
  }

  const htmlRe = /<a\b[^>]*href=(["'])(https?:\/\/.*?)\1[^>]*>([\s\S]*?)<\/a>/gi;
  for (const match of html.matchAll(htmlRe)) {
    structured.push({
      index: match.index ?? 0,
      end: (match.index ?? 0) + match[0].length,
      label: match[3],
      url: match[2],
      source: html,
    });
  }

  structured.sort((a, b) => a.index - b.index);

  for (let i = 0; i < structured.length; i++) {
    const link = structured[i];
    const next = structured[i + 1];
    const contextEnd = next && next.source === link.source
      ? Math.min(next.index, link.end + 1400)
      : link.end + 1400;
    const context = link.source.slice(link.end, contextEnd);
    addCandidate(message, link.url, link.label, context);
  }

  if (!structured.length) {
    const blob = [plain, html].filter(Boolean).join(NL);
    const urlRe = /https?:\/\/[^\s<>"')\]]+/g;
    for (const match of blob.matchAll(urlRe)) {
      const url = canonicalTarget(match[0]);
      if (!url || seen.has(url)) continue;
      const subject = cleanText(message.Subject || message.subject || 'Google Alert');
      if (!subject) continue;
      seen.add(url);
      out.push({
        json: {
          title: subject,
          link: url,
          contentSnippet: cleanText(message.snippet || plain).slice(0, 5000),
          isoDate: message.Date || message.date || message.internalDate || '',
          creator: 'Google Alerts',
          _source_type: 'GMAIL_ALERT',
        },
      });
    }
  }
}

